function syncLinkedItems(){if(!s.layouts||!s.size)return;const otherKey=s.size==="mobile"?"desktop":"mobile";const other=s.layouts[otherKey];if(!other)return;other.elements=other.elements||[];for(const item of (s.elements||[])){if(item.linkAcrossViews===false)continue;let match=other.elements.find(v=>v.id===item.id);if(!match){match=counterpartGeometry(item,otherKey,other.elements);other.elements.push(match)}copySharedItemFields(item,match)}}
