function autoAvoidTextOverlaps(){
 const c=$("previewCanvas");if(!c)return;
 const cw=c.clientWidth,ch=c.clientHeight;if(!cw||!ch)return;
 const images=[...c.querySelectorAll('.preview-element[data-type="image"]:not([data-background="true"])')];
 const texts=[...c.querySelectorAll('.preview-element[data-type="text"]')];
 const rectFor=node=>{
  const item=s.elements.find(v=>v.id===node.dataset.id);if(!item)return null;
  const left=(Number(item.x)||0)/100*cw,top=(Number(item.y)||0)/100*ch;
  const width=node.offsetWidth,height=node.offsetHeight;
  return {left,top,right:left+width,bottom:top+height,width,height,item};
 };
 const imageRects=images.map(rectFor).filter(Boolean);
 for(const node of texts){
  const current=rectFor(node);if(!current)continue;
  if(!imageRects.some(r=>overlaps(current,r,8)))continue;
  const {item}=current, gap=18;
  const candidates=[];
  for(const im of imageRects){
   candidates.push(
    [im.left-current.width-gap,current.top],
    [im.right+gap,current.top],
    [current.left,im.top-current.height-gap],
    [current.left,im.bottom+gap]
   );
  }
  candidates.push([24,Math.min(ch-current.height-24,current.top+24)]);
  let best=null,bestCost=Infinity;
  for(const [rawX,rawY] of candidates){
   const left=Math.max(12,Math.min(cw-current.width-12,rawX));
   const top=Math.max(72,Math.min(ch-current.height-12,rawY));
   const test={left,top,right:left+current.width,bottom:top+current.height};
   if(imageRects.some(im=>overlaps(test,im,8)))continue;
   const cost=Math.abs(left-current.left)+Math.abs(top-current.top)*1.15;
   if(cost<bestCost){bestCost=cost;best=[left,top]}
  }
  if(best){
   item.x=best[0]/cw*100;item.y=best[1]/ch*100;
   node.style.left=item.x+"%";node.style.top=item.y+"%";
   Object.assign(current,{left:best[0],top:best[1],right:best[0]+current.width,bottom:best[1]+current.height});
  }
 }
}


function addCanvasTextTools(c){
 const x=el();if(!x||x.type!=="text"||x.locked)return;
 const node=c.querySelector('[data-id="'+x.id+'"]');if(!node)return;
 ["nw","n","ne","e","se","s","sw","w"].forEach(pos=>{
  const h=document.createElement("button");h.type="button";h.className="canvas-resize-handle text-resize-handle handle-"+pos;
  h.setAttribute("aria-label","Resize text "+pos);h.setAttribute("data-text-resize","true");
  const left=pos.includes("w")?node.offsetLeft:pos.includes("e")?node.offsetLeft+node.offsetWidth:node.offsetLeft+node.offsetWidth/2;
  const top=pos.includes("n")?node.offsetTop:pos.includes("s")?node.offsetTop+node.offsetHeight:node.offsetTop+node.offsetHeight/2;
  h.style.left=(left/Math.max(1,c.clientWidth)*100)+"%";h.style.top=(top/Math.max(1,c.clientHeight)*100)+"%";
  h.addEventListener("pointerdown",e=>{e.preventDefault();e.stopPropagation();resizeTextStart(e,pos,x,c)});
  h.addEventListener("click",e=>{e.preventDefault();e.stopPropagation()});
  c.append(h);
 });
}

